    private IDatabase dbInterface;

    public DBApp testDBApp() {
        return new DBApp(dbInterface);
    }

    @Test
    public void getMyTables_NoException() {
        DBApp instance = testDBApp();
        instance.getMyTables();
        assertNotNull(instance.getMyTables());
    }

    @Test(expected = DBAppException.class)
    public void init_ThrowsException() {
        testDBApp().init();
    }

    @Test
    public void createTable_NameNotEmpty() {
        DBApp instance = testDBApp();
        instance.createTable("TableName", "ClusteringKeyColumn", new Hashtable<>(), new Hashtable<>(), new Hashtable<>());
        Mockito.verifyNoErrorsOrExceptions(instance.getReader());
    }

    @Test(expected = DBAppException.class)
    public void createTable_InvalidName() {
        DBApp instance = testDBApp();
        instance.createTable("", "ClusteringKeyColumn", new Hashtable<>(), new Hashtable<>(), new Hashtable<>());
    }

    @Test
    public void insertIntoTable_NameNotEmpty() {
        DBApp instance = testDBApp();
        instance.insertIntoTable("TableName", new Hashtable<>());
        Mockito.verifyNoErrorsOrExceptions(instance.getWriter());
    }

    @Test(expected = DBAppException.class)
    public void insertIntoTable_InvalidName() {
        DBApp instance = testDBApp();
        instance.insertIntoTable("", new Hashtable<>());
    }

    @Test
    public void updateTable_NameNotEmpty() {
        DBApp instance = testDBApp();
        instance.updateTable("TableName", "ClusteringKeyValue", new Hashtable<>());
        Mockito.verifyNoErrorsOrExceptions(instance.getReader());
    }

    @Test(expected = DBAppException.class)
    public void updateTable_InvalidName() {
        DBApp instance = testDBApp();
        instance.updateTable("", "ClusteringKeyValue", new Hashtable<>());
    }

    @Test
    public void deleteFromTable_NameNotEmpty() {
        DBApp instance = testDBApp();
        instance.deleteFromTable("TableName", new Hashtable<>());
        Mockito.verifyNoErrorsOrExceptions(instance.getReader());
    }

    @Test(expected = DBAppException.class)
    public void deleteFromTable_InvalidName() {
        DBApp instance = testDBApp();
        instance.deleteFromTable("", new Hashtable<>());
    }

    @Test
    public void selectFromTable_NoSQLTermsArray() {
        DBApp instance = testDBApp();
        instance.selectFromTable(new SQLTerm[0], new String[0]);
        assertNotNull(instance.getReader());
    }

    @Test(expected = DBAppException.class)
    public void selectFromTable_EmptySQLTermsArray() {
        DBApp instance = testDBApp();
        instance.selectFromTable(new SQLTerm[0], new String[]{});
    }
